local function cukxwnvgz()
	local alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local data = ucvqbacgh.concat(nnwjbrudp)
	local out = {}
	local n, bits, val = 1, 0, 0
	for i = 1, #data do
		local ch = xdajhhedy.sub(data, i, i)
		if ch ~= "=" and ch ~= " " then
			local p = xdajhhedy.find(alpha, ch, 1, true)
			if p then
				val = val * 64 + (p - 1)
				bits = bits + 6
				if bits >= 8 then
					bits = bits - 8
					out[n] = twaugzxzu.floor(val / (2 ^ bits)) % 256
					n = n + 1
					val = val % (2 ^ bits)
				end
			end
		end
	end
	local parts, buf, bi = {}, {}, 0
	for i = 1, #out do
		local x = out[i]
		local k = mjegmdcpd[((i - 1) % 32) + 1]
		local r = ((i - 1) * 7 + 13) % 256
		local z
		if bit32 and bit32.bxor then
